sequence.block:
// Helper variables
__var savedAP = __ap;
__var ffcrValue = 0x00000000;
__var etbStatus = 0x00000000;

Message(0, "Begin CS_ETB___INSTANCE_INDEX___Configure @0x%08X, AP 0x%08X", ETB___INSTANCE_INDEX___ADDRESS, ETB___INSTANCE_INDEX___AP);
__ap = ETB___INSTANCE_INDEX___AP;                             // Set AP

// Configure ETB
Write32(ETB___INSTANCE_INDEX___ADDRESS + 0x020, 0x00000000);  // Disable ETB before configuring
etbStatus = Read32(ETB___INSTANCE_INDEX___ADDRESS + 0x00C);

// Helper variables
__var ffcrValue = 0x00000000;
__var savedAP = __ap;

Message(0, "Begin CS_ETB___INSTANCE_INDEX___Capture @0x%08X, AP 0x%08X", ETB___INSTANCE_INDEX___ADDRESS, ETB___INSTANCE_INDEX___AP);

__ap = ETB___INSTANCE_INDEX___AP;                             // Set AP
ffcrValue  = Read32(ETB___INSTANCE_INDEX___ADDRESS + 0x304);
ffcrValue |= 0x00000002;                                      // FFCR: Enable Formatter
Write32(ETB___INSTANCE_INDEX___ADDRESS + 0x304, ffcrValue);
Write32(ETB___INSTANCE_INDEX___ADDRESS + 0x01C, ETB___INSTANCE_INDEX___TRIGGER_COUNT); // TRG: Number of words to capture after trigger
Write32(ETB___INSTANCE_INDEX___ADDRESS + 0x018, 0x00000000);  // Init RwP
Write32(ETB___INSTANCE_INDEX___ADDRESS + 0x014, 0x00000000);  // Init RRP
Write32(ETB___INSTANCE_INDEX___ADDRESS + 0x020, 0x00000001);  // Enable ETB
__ap = savedAP;

Message(0, "End CS_ETB___INSTANCE_INDEX___Capture @0x%08X, AP 0x%08X", ETB___INSTANCE_INDEX___ADDRESS, ETB___INSTANCE_INDEX___AP);

// Helper variables
__var savedAP     = __ap;
__var ffcrValue   = 0x00000000;
__var etbStatus   = 0x00000000;

Message(0, "Begin CS_ETB___INSTANCE_INDEX___Flush @0x%08X, AP 0x%08X", ETB___INSTANCE_INDEX___ADDRESS, ETB___INSTANCE_INDEX___AP);

__ap = ETB___INSTANCE_INDEX___AP;  // Set AP

// Flush ETB first
ffcrValue = Read32(ETB___INSTANCE_INDEX___ADDRESS + 0x304);
ffcrValue &= ~(0x00001040);    // Clear StopOnFlush and FlushOnManual
ffcrValue |= 0x00001000;           // Stop after the manual flush completes
Write32(ETB___INSTANCE_INDEX___ADDRESS + 0x304, ffcrValue);
ffcrValue |= 0x00000040;           // Trigger manual flush
Write32(ETB___INSTANCE_INDEX___ADDRESS + 0x304, ffcrValue);

// Disable ETB after flush until next run/step
Write32(ETB___INSTANCE_INDEX___ADDRESS + 0x020, 0x00000000);
etbStatus = Read32(ETB___INSTANCE_INDEX___ADDRESS + 0x00C);

// Helper variables
__var savedAP       = __ap;
__var etbStatus     = 0x00000000;
__var bufferWords   = 0x00000000;
__var readPointer   = 0x00000000;
__var writePointer  = 0x00000000;
__var wordsToRead   = 0x00000000;
__var bytesToRead   = 0x00000000;
__var bytesStreamed = 0x00000000;

Message(0, "Begin CS_ETB___INSTANCE_INDEX___Read_Buffer @0x%08X, AP 0x%08X", ETB___INSTANCE_INDEX___ADDRESS, ETB___INSTANCE_INDEX___AP);

__ap = ETB___INSTANCE_INDEX___AP; // Set AP

// The legacy ETB RDP, RRP, and RWP registers use trace-RAM word counts.
bufferWords  = Read32(ETB___INSTANCE_INDEX___ADDRESS + 0x004);
etbStatus    = Read32(ETB___INSTANCE_INDEX___ADDRESS + 0x00C);
readPointer  = Read32(ETB___INSTANCE_INDEX___ADDRESS + 0x014);
writePointer = Read32(ETB___INSTANCE_INDEX___ADDRESS + 0x018);

control.block:
// STS.Full distinguishes a wrapped/full buffer from an empty buffer
// when the read and write pointers are equal.
wordsToRead = bufferWords;
// RWP identifies the oldest retained trace after the buffer wraps.
Write32(ETB___INSTANCE_INDEX___ADDRESS + 0x014, writePointer); // Rebase RRP for chronological output

// RRD reads 32-bit trace-RAM words and advances the ETB RRP register.
BufferRead(0, 0, ETB___INSTANCE_INDEX___ADDRESS + 0x010, bytesToRead, 32);
// Stream to single unnamed trace buffer in system by default, insert name if multiple
// named buffers specified in PDSC. Decide which xxx_Read_Buffer sequence to call based
// on TraceBufferSelected().
bytesStreamed = BufferStreamOut(0, 0, bytesToRead, "", 1, 0);
Message(0, "Streamed %d of %d ETB trace bytes", bytesStreamed, bytesToRead);
